INSERT INTO questions (section, part, sort_order, payload) VALUES ('reading', 'Reading', 105, $${"id": "RD-16", "kind": "reading", "part": "Reading", "passageId": "RD-P2", "passageTitle": "The Axolotl: Master of Regeneration", "passageText": "The axolotl, a salamander native to the lakes around Mexico City, looks like a creature that never finished growing up, and in a sense it never did. Through a phenomenon called neoteny, it retains its larval features, including feathery external gills, throughout its adult life. But the axolotl's strangest trait is not its appearance. It can regrow lost limbs, jaws, and portions of its spinal cord, and even repair damaged sections of its heart and brain, all without forming scars.\n\nWhen an axolotl loses a limb, cells near the wound revert to a less specialized state and gather into a structure called a blastema, a mass of unspecialized cells that gradually rebuilds the missing part, bone, muscle, nerves, and skin, in the correct arrangement. Mammals respond to serious injury very differently: their wounds close quickly but with scar tissue, and complex structures are never rebuilt. Researchers believe that differences in the immune response, particularly in how certain immune cells behave at the wound site, help explain why the axolotl regenerates while humans merely scar.\n\nIronically, this master of regeneration is disappearing from its natural home. In the wild, axolotls survive only in the canals of Lake Xochimilco, where they have been driven to the brink of extinction by pollution, the draining of their habitat, and introduced predators such as tilapia and carp. They are now classified as critically endangered. In laboratories and aquariums around the world, however, they thrive, bred by the thousands for research and the pet trade.\n\nThat contrast is precisely what makes the axolotl so valuable to science. By comparing its scar-free healing with our own, researchers hope to uncover therapies that could one day help human wounds heal more completely. The effort gained a powerful tool in 2018, when scientists sequenced the axolotl genome, all 32 billion base pairs of it, roughly ten times the size of the human genome and the largest genome sequenced at that time. Hidden within that enormous instruction book may be the secrets of regeneration itself.", "stem": "It can be inferred from paragraph 2 that when mammals suffer serious injuries, they", "options": ["regrow the damaged tissue completely", "form a blastema at the wound site", "heal with scar tissue instead of regenerating", "revert their cells to a less specialized state"], "answer": 2, "explanation": "Paragraf 2 menjelaskan luka mamalia menutup 'with scar tissue, and complex structures are never rebuilt'. Pilihan A, B, dan D justru ciri-ciri axolotl, bukan mamalia.", "qtype": "inference"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('reading', 'Reading', 106, $${"id": "RD-17", "kind": "reading", "part": "Reading", "passageId": "RD-P2", "passageTitle": "The Axolotl: Master of Regeneration", "passageText": "The axolotl, a salamander native to the lakes around Mexico City, looks like a creature that never finished growing up, and in a sense it never did. Through a phenomenon called neoteny, it retains its larval features, including feathery external gills, throughout its adult life. But the axolotl's strangest trait is not its appearance. It can regrow lost limbs, jaws, and portions of its spinal cord, and even repair damaged sections of its heart and brain, all without forming scars.\n\nWhen an axolotl loses a limb, cells near the wound revert to a less specialized state and gather into a structure called a blastema, a mass of unspecialized cells that gradually rebuilds the missing part, bone, muscle, nerves, and skin, in the correct arrangement. Mammals respond to serious injury very differently: their wounds close quickly but with scar tissue, and complex structures are never rebuilt. Researchers believe that differences in the immune response, particularly in how certain immune cells behave at the wound site, help explain why the axolotl regenerates while humans merely scar.\n\nIronically, this master of regeneration is disappearing from its natural home. In the wild, axolotls survive only in the canals of Lake Xochimilco, where they have been driven to the brink of extinction by pollution, the draining of their habitat, and introduced predators such as tilapia and carp. They are now classified as critically endangered. In laboratories and aquariums around the world, however, they thrive, bred by the thousands for research and the pet trade.\n\nThat contrast is precisely what makes the axolotl so valuable to science. By comparing its scar-free healing with our own, researchers hope to uncover therapies that could one day help human wounds heal more completely. The effort gained a powerful tool in 2018, when scientists sequenced the axolotl genome, all 32 billion base pairs of it, roughly ten times the size of the human genome and the largest genome sequenced at that time. Hidden within that enormous instruction book may be the secrets of regeneration itself.", "stem": "According to the passage, all of the following can be regenerated by the axolotl EXCEPT", "options": ["an entire head", "lost limbs", "portions of the spinal cord", "damaged sections of the heart"], "answer": 0, "explanation": "Paragraf 1 menyebut anggota tubuh, rahang, sumsum tulang belakang, jantung, dan otak, tetapi tidak pernah menyebut 'an entire head' (seluruh kepala). Pilihan B, C, dan D semuanya dinyatakan dalam teks.", "qtype": "unstated detail"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('reading', 'Reading', 107, $${"id": "RD-18", "kind": "reading", "part": "Reading", "passageId": "RD-P2", "passageTitle": "The Axolotl: Master of Regeneration", "passageText": "The axolotl, a salamander native to the lakes around Mexico City, looks like a creature that never finished growing up, and in a sense it never did. Through a phenomenon called neoteny, it retains its larval features, including feathery external gills, throughout its adult life. But the axolotl's strangest trait is not its appearance. It can regrow lost limbs, jaws, and portions of its spinal cord, and even repair damaged sections of its heart and brain, all without forming scars.\n\nWhen an axolotl loses a limb, cells near the wound revert to a less specialized state and gather into a structure called a blastema, a mass of unspecialized cells that gradually rebuilds the missing part, bone, muscle, nerves, and skin, in the correct arrangement. Mammals respond to serious injury very differently: their wounds close quickly but with scar tissue, and complex structures are never rebuilt. Researchers believe that differences in the immune response, particularly in how certain immune cells behave at the wound site, help explain why the axolotl regenerates while humans merely scar.\n\nIronically, this master of regeneration is disappearing from its natural home. In the wild, axolotls survive only in the canals of Lake Xochimilco, where they have been driven to the brink of extinction by pollution, the draining of their habitat, and introduced predators such as tilapia and carp. They are now classified as critically endangered. In laboratories and aquariums around the world, however, they thrive, bred by the thousands for research and the pet trade.\n\nThat contrast is precisely what makes the axolotl so valuable to science. By comparing its scar-free healing with our own, researchers hope to uncover therapies that could one day help human wounds heal more completely. The effort gained a powerful tool in 2018, when scientists sequenced the axolotl genome, all 32 billion base pairs of it, roughly ten times the size of the human genome and the largest genome sequenced at that time. Hidden within that enormous instruction book may be the secrets of regeneration itself.", "stem": "The word 'brink' in paragraph 3 is closest in meaning to", "options": ["center", "edge", "depth", "bottom"], "answer": 1, "explanation": "Frasa 'driven to the brink of extinction' berarti didorong ke tepi jurang kepunahan, jadi 'edge'. Pilihan A, C, dan D tidak sesuai dengan makna kiasan ini.", "qtype": "vocabulary"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('reading', 'Reading', 108, $${"id": "RD-19", "kind": "reading", "part": "Reading", "passageId": "RD-P2", "passageTitle": "The Axolotl: Master of Regeneration", "passageText": "The axolotl, a salamander native to the lakes around Mexico City, looks like a creature that never finished growing up, and in a sense it never did. Through a phenomenon called neoteny, it retains its larval features, including feathery external gills, throughout its adult life. But the axolotl's strangest trait is not its appearance. It can regrow lost limbs, jaws, and portions of its spinal cord, and even repair damaged sections of its heart and brain, all without forming scars.\n\nWhen an axolotl loses a limb, cells near the wound revert to a less specialized state and gather into a structure called a blastema, a mass of unspecialized cells that gradually rebuilds the missing part, bone, muscle, nerves, and skin, in the correct arrangement. Mammals respond to serious injury very differently: their wounds close quickly but with scar tissue, and complex structures are never rebuilt. Researchers believe that differences in the immune response, particularly in how certain immune cells behave at the wound site, help explain why the axolotl regenerates while humans merely scar.\n\nIronically, this master of regeneration is disappearing from its natural home. In the wild, axolotls survive only in the canals of Lake Xochimilco, where they have been driven to the brink of extinction by pollution, the draining of their habitat, and introduced predators such as tilapia and carp. They are now classified as critically endangered. In laboratories and aquariums around the world, however, they thrive, bred by the thousands for research and the pet trade.\n\nThat contrast is precisely what makes the axolotl so valuable to science. By comparing its scar-free healing with our own, researchers hope to uncover therapies that could one day help human wounds heal more completely. The effort gained a powerful tool in 2018, when scientists sequenced the axolotl genome, all 32 billion base pairs of it, roughly ten times the size of the human genome and the largest genome sequenced at that time. Hidden within that enormous instruction book may be the secrets of regeneration itself.", "stem": "Why do scientists study regeneration in the axolotl?", "options": ["To breed more colorful aquarium pets", "To reintroduce axolotls into Lake Titicaca", "To find ways to improve wound healing in humans", "To prove that mammals cannot form scars"], "answer": 2, "explanation": "Paragraf 4 menyatakan para peneliti berharap menemukan terapi agar luka manusia sembuh lebih sempurna. Pilihan A dan B tidak disebut, sedangkan D berlawanan dengan fakta (mamalia memang membentuk jaringan parut).", "qtype": "stated detail"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('reading', 'Reading', 109, $${"id": "RD-20", "kind": "reading", "part": "Reading", "passageId": "RD-P2", "passageTitle": "The Axolotl: Master of Regeneration", "passageText": "The axolotl, a salamander native to the lakes around Mexico City, looks like a creature that never finished growing up, and in a sense it never did. Through a phenomenon called neoteny, it retains its larval features, including feathery external gills, throughout its adult life. But the axolotl's strangest trait is not its appearance. It can regrow lost limbs, jaws, and portions of its spinal cord, and even repair damaged sections of its heart and brain, all without forming scars.\n\nWhen an axolotl loses a limb, cells near the wound revert to a less specialized state and gather into a structure called a blastema, a mass of unspecialized cells that gradually rebuilds the missing part, bone, muscle, nerves, and skin, in the correct arrangement. Mammals respond to serious injury very differently: their wounds close quickly but with scar tissue, and complex structures are never rebuilt. Researchers believe that differences in the immune response, particularly in how certain immune cells behave at the wound site, help explain why the axolotl regenerates while humans merely scar.\n\nIronically, this master of regeneration is disappearing from its natural home. In the wild, axolotls survive only in the canals of Lake Xochimilco, where they have been driven to the brink of extinction by pollution, the draining of their habitat, and introduced predators such as tilapia and carp. They are now classified as critically endangered. In laboratories and aquariums around the world, however, they thrive, bred by the thousands for research and the pet trade.\n\nThat contrast is precisely what makes the axolotl so valuable to science. By comparing its scar-free healing with our own, researchers hope to uncover therapies that could one day help human wounds heal more completely. The effort gained a powerful tool in 2018, when scientists sequenced the axolotl genome, all 32 billion base pairs of it, roughly ten times the size of the human genome and the largest genome sequenced at that time. Hidden within that enormous instruction book may be the secrets of regeneration itself.", "stem": "The author's primary purpose in the passage is to", "options": ["argue for a ban on the axolotl pet trade", "describe the geography of Mexico City", "warn that tilapia are dangerous to humans", "describe an extraordinary animal and explain its scientific importance"], "answer": 3, "explanation": "Keseluruhan teks mendeskripsikan axolotl dan menjelaskan mengapa ia penting bagi ilmu pengetahuan. Tidak ada argumen pelarangan perdagangan (A), deskripsi geografi (B), atau peringatan tentang bahaya tilapia bagi manusia (C).", "qtype": "purpose"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('reading', 'Reading', 110, $${"id": "RD-21", "kind": "reading", "part": "Reading", "passageId": "RD-P3", "passageTitle": "The Hunt for Habitable Exoplanets", "passageText": "In 1992, astronomers confirmed the first planets ever found outside our solar system, and the floodgates opened. More than five thousand exoplanets have since been cataloged, and most were discovered by a single clever technique: the transit method. When a planet passes directly between its star and Earth, it blocks a tiny fraction of the star's light, causing a slight, periodic dimming. The Kepler space telescope, launched in 2009, stared at a single patch of sky for years, measuring these minute flickers, and in doing so revealed thousands of new worlds.\n\nFinding a planet is only the first step; the deeper question is whether any of them could support life. Astronomers focus on the habitable zone, sometimes called the Goldilocks zone, the range of distances from a star where temperatures might allow liquid water to exist on a planet's surface. Too close, and water boils away; too far, and it freezes solid. The exact boundaries depend on the type of star and the thickness of the planet's atmosphere, but this zone has become the primary hunting ground in the search for life.\n\nOne of the most promising hunting grounds is TRAPPIST-1, an ultracool dwarf star about 40 light-years from Earth. In 2017, astronomers announced that it hosts seven planets, each roughly the size of Earth, and three of them orbit within the star's habitable zone. The system is remarkably compact: all seven worlds circle their star at distances smaller than Mercury's orbit around the Sun, and they crowd so close together that from the surface of one, its neighbors would loom large in the sky.\n\nDetection, however, is not the same as habitability. A planet in the habitable zone might still be airless, or it might suffer sterilizing flares from an active star, or lack the magnetic field needed to protect an atmosphere. The James Webb Space Telescope can now probe the atmospheres of these distant worlds, and it may one day detect water vapor, methane, or oxygen, gases that, in combination, could be biosignatures of life. Until then, the habitable zone remains what it has always been: the best place to start looking.", "stem": "What is the main idea of the passage?", "options": ["The Kepler telescope proved that life exists on other planets.", "The transit method is the only way to find exoplanets.", "TRAPPIST-1 is the closest star to Earth.", "Astronomers search for habitable exoplanets by looking for planets in the habitable zone, though detection alone does not guarantee habitability."], "answer": 3, "explanation": "Gagasan utama merangkum metode transit, zona laik huni, contoh TRAPPIST-1, dan catatan kehati-hatian di paragraf 4. Pilihan A salah karena keberadaan kehidupan belum terbukti. Pilihan B salah karena teks menyebut metode transit menemukan 'most', bukan satu-satunya. Pilihan C salah karena TRAPPIST-1 berjarak 40 tahun cahaya, bukan yang terdekat.", "qtype": "main idea"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('reading', 'Reading', 111, $${"id": "RD-22", "kind": "reading", "part": "Reading", "passageId": "RD-P3", "passageTitle": "The Hunt for Habitable Exoplanets", "passageText": "In 1992, astronomers confirmed the first planets ever found outside our solar system, and the floodgates opened. More than five thousand exoplanets have since been cataloged, and most were discovered by a single clever technique: the transit method. When a planet passes directly between its star and Earth, it blocks a tiny fraction of the star's light, causing a slight, periodic dimming. The Kepler space telescope, launched in 2009, stared at a single patch of sky for years, measuring these minute flickers, and in doing so revealed thousands of new worlds.\n\nFinding a planet is only the first step; the deeper question is whether any of them could support life. Astronomers focus on the habitable zone, sometimes called the Goldilocks zone, the range of distances from a star where temperatures might allow liquid water to exist on a planet's surface. Too close, and water boils away; too far, and it freezes solid. The exact boundaries depend on the type of star and the thickness of the planet's atmosphere, but this zone has become the primary hunting ground in the search for life.\n\nOne of the most promising hunting grounds is TRAPPIST-1, an ultracool dwarf star about 40 light-years from Earth. In 2017, astronomers announced that it hosts seven planets, each roughly the size of Earth, and three of them orbit within the star's habitable zone. The system is remarkably compact: all seven worlds circle their star at distances smaller than Mercury's orbit around the Sun, and they crowd so close together that from the surface of one, its neighbors would loom large in the sky.\n\nDetection, however, is not the same as habitability. A planet in the habitable zone might still be airless, or it might suffer sterilizing flares from an active star, or lack the magnetic field needed to protect an atmosphere. The James Webb Space Telescope can now probe the atmospheres of these distant worlds, and it may one day detect water vapor, methane, or oxygen, gases that, in combination, could be biosignatures of life. Until then, the habitable zone remains what it has always been: the best place to start looking.", "stem": "According to paragraph 1, the transit method detects exoplanets by", "options": ["observing a slight, periodic dimming of a star's light", "photographing the planets directly", "measuring the star's temperature", "listening for radio signals from the planets"], "answer": 0, "explanation": "Paragraf 1 menjelaskan bahwa planet menghalangi sebagian kecil cahaya bintang sehingga terjadi peredupan ringan yang berkala. Pilihan B, C, dan D tidak sesuai dengan deskripsi metode tersebut.", "qtype": "stated detail"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('reading', 'Reading', 112, $${"id": "RD-23", "kind": "reading", "part": "Reading", "passageId": "RD-P3", "passageTitle": "The Hunt for Habitable Exoplanets", "passageText": "In 1992, astronomers confirmed the first planets ever found outside our solar system, and the floodgates opened. More than five thousand exoplanets have since been cataloged, and most were discovered by a single clever technique: the transit method. When a planet passes directly between its star and Earth, it blocks a tiny fraction of the star's light, causing a slight, periodic dimming. The Kepler space telescope, launched in 2009, stared at a single patch of sky for years, measuring these minute flickers, and in doing so revealed thousands of new worlds.\n\nFinding a planet is only the first step; the deeper question is whether any of them could support life. Astronomers focus on the habitable zone, sometimes called the Goldilocks zone, the range of distances from a star where temperatures might allow liquid water to exist on a planet's surface. Too close, and water boils away; too far, and it freezes solid. The exact boundaries depend on the type of star and the thickness of the planet's atmosphere, but this zone has become the primary hunting ground in the search for life.\n\nOne of the most promising hunting grounds is TRAPPIST-1, an ultracool dwarf star about 40 light-years from Earth. In 2017, astronomers announced that it hosts seven planets, each roughly the size of Earth, and three of them orbit within the star's habitable zone. The system is remarkably compact: all seven worlds circle their star at distances smaller than Mercury's orbit around the Sun, and they crowd so close together that from the surface of one, its neighbors would loom large in the sky.\n\nDetection, however, is not the same as habitability. A planet in the habitable zone might still be airless, or it might suffer sterilizing flares from an active star, or lack the magnetic field needed to protect an atmosphere. The James Webb Space Telescope can now probe the atmospheres of these distant worlds, and it may one day detect water vapor, methane, or oxygen, gases that, in combination, could be biosignatures of life. Until then, the habitable zone remains what it has always been: the best place to start looking.", "stem": "The word 'compact' in paragraph 3 is closest in meaning to", "options": ["ancient", "tightly packed", "unstable", "poorly understood"], "answer": 1, "explanation": "Konteksnya: ketujuh planet mengorbit pada jarak yang lebih kecil dari orbit Merkurius, artinya sistemnya rapat atau padat, jadi 'tightly packed'. Pilihan A, C, dan D tidak sesuai konteks.", "qtype": "vocabulary"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('reading', 'Reading', 113, $${"id": "RD-24", "kind": "reading", "part": "Reading", "passageId": "RD-P3", "passageTitle": "The Hunt for Habitable Exoplanets", "passageText": "In 1992, astronomers confirmed the first planets ever found outside our solar system, and the floodgates opened. More than five thousand exoplanets have since been cataloged, and most were discovered by a single clever technique: the transit method. When a planet passes directly between its star and Earth, it blocks a tiny fraction of the star's light, causing a slight, periodic dimming. The Kepler space telescope, launched in 2009, stared at a single patch of sky for years, measuring these minute flickers, and in doing so revealed thousands of new worlds.\n\nFinding a planet is only the first step; the deeper question is whether any of them could support life. Astronomers focus on the habitable zone, sometimes called the Goldilocks zone, the range of distances from a star where temperatures might allow liquid water to exist on a planet's surface. Too close, and water boils away; too far, and it freezes solid. The exact boundaries depend on the type of star and the thickness of the planet's atmosphere, but this zone has become the primary hunting ground in the search for life.\n\nOne of the most promising hunting grounds is TRAPPIST-1, an ultracool dwarf star about 40 light-years from Earth. In 2017, astronomers announced that it hosts seven planets, each roughly the size of Earth, and three of them orbit within the star's habitable zone. The system is remarkably compact: all seven worlds circle their star at distances smaller than Mercury's orbit around the Sun, and they crowd so close together that from the surface of one, its neighbors would loom large in the sky.\n\nDetection, however, is not the same as habitability. A planet in the habitable zone might still be airless, or it might suffer sterilizing flares from an active star, or lack the magnetic field needed to protect an atmosphere. The James Webb Space Telescope can now probe the atmospheres of these distant worlds, and it may one day detect water vapor, methane, or oxygen, gases that, in combination, could be biosignatures of life. Until then, the habitable zone remains what it has always been: the best place to start looking.", "stem": "The word 'it' in paragraph 4 refers to", "options": ["the atmospheres", "these distant worlds", "the James Webb Space Telescope", "the star"], "answer": 2, "explanation": "Kata 'it' merujuk pada subjek klausa sebelumnya, yaitu 'The James Webb Space Telescope'. Pilihan A dan B adalah objek yang diselidiki, bukan acuannya.", "qtype": "pronoun reference"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('reading', 'Reading', 114, $${"id": "RD-25", "kind": "reading", "part": "Reading", "passageId": "RD-P3", "passageTitle": "The Hunt for Habitable Exoplanets", "passageText": "In 1992, astronomers confirmed the first planets ever found outside our solar system, and the floodgates opened. More than five thousand exoplanets have since been cataloged, and most were discovered by a single clever technique: the transit method. When a planet passes directly between its star and Earth, it blocks a tiny fraction of the star's light, causing a slight, periodic dimming. The Kepler space telescope, launched in 2009, stared at a single patch of sky for years, measuring these minute flickers, and in doing so revealed thousands of new worlds.\n\nFinding a planet is only the first step; the deeper question is whether any of them could support life. Astronomers focus on the habitable zone, sometimes called the Goldilocks zone, the range of distances from a star where temperatures might allow liquid water to exist on a planet's surface. Too close, and water boils away; too far, and it freezes solid. The exact boundaries depend on the type of star and the thickness of the planet's atmosphere, but this zone has become the primary hunting ground in the search for life.\n\nOne of the most promising hunting grounds is TRAPPIST-1, an ultracool dwarf star about 40 light-years from Earth. In 2017, astronomers announced that it hosts seven planets, each roughly the size of Earth, and three of them orbit within the star's habitable zone. The system is remarkably compact: all seven worlds circle their star at distances smaller than Mercury's orbit around the Sun, and they crowd so close together that from the surface of one, its neighbors would loom large in the sky.\n\nDetection, however, is not the same as habitability. A planet in the habitable zone might still be airless, or it might suffer sterilizing flares from an active star, or lack the magnetic field needed to protect an atmosphere. The James Webb Space Telescope can now probe the atmospheres of these distant worlds, and it may one day detect water vapor, methane, or oxygen, gases that, in combination, could be biosignatures of life. Until then, the habitable zone remains what it has always been: the best place to start looking.", "stem": "According to the passage, the TRAPPIST-1 system", "options": ["contains seven planets roughly the size of Earth", "was discovered by the Kepler telescope", "has no planets in its habitable zone", "is the closest star system to Earth"], "answer": 0, "explanation": "Paragraf 3 menyatakan sistem ini memiliki tujuh planet seukuran Bumi dan tiga di antaranya berada di zona laik huni. Pilihan B, C, dan D bertentangan dengan teks.", "qtype": "stated detail"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('reading', 'Reading', 115, $${"id": "RD-26", "kind": "reading", "part": "Reading", "passageId": "RD-P3", "passageTitle": "The Hunt for Habitable Exoplanets", "passageText": "In 1992, astronomers confirmed the first planets ever found outside our solar system, and the floodgates opened. More than five thousand exoplanets have since been cataloged, and most were discovered by a single clever technique: the transit method. When a planet passes directly between its star and Earth, it blocks a tiny fraction of the star's light, causing a slight, periodic dimming. The Kepler space telescope, launched in 2009, stared at a single patch of sky for years, measuring these minute flickers, and in doing so revealed thousands of new worlds.\n\nFinding a planet is only the first step; the deeper question is whether any of them could support life. Astronomers focus on the habitable zone, sometimes called the Goldilocks zone, the range of distances from a star where temperatures might allow liquid water to exist on a planet's surface. Too close, and water boils away; too far, and it freezes solid. The exact boundaries depend on the type of star and the thickness of the planet's atmosphere, but this zone has become the primary hunting ground in the search for life.\n\nOne of the most promising hunting grounds is TRAPPIST-1, an ultracool dwarf star about 40 light-years from Earth. In 2017, astronomers announced that it hosts seven planets, each roughly the size of Earth, and three of them orbit within the star's habitable zone. The system is remarkably compact: all seven worlds circle their star at distances smaller than Mercury's orbit around the Sun, and they crowd so close together that from the surface of one, its neighbors would loom large in the sky.\n\nDetection, however, is not the same as habitability. A planet in the habitable zone might still be airless, or it might suffer sterilizing flares from an active star, or lack the magnetic field needed to protect an atmosphere. The James Webb Space Telescope can now probe the atmospheres of these distant worlds, and it may one day detect water vapor, methane, or oxygen, gases that, in combination, could be biosignatures of life. Until then, the habitable zone remains what it has always been: the best place to start looking.", "stem": "It can be inferred from paragraph 1 that the transit method can only detect planets that", "options": ["are larger than Jupiter", "orbit very close to Earth", "have intelligent life", "pass directly between their star and Earth"], "answer": 3, "explanation": "Metode ini bekerja ketika planet 'passes directly between its star and Earth', sehingga orbit planet harus sejajar dengan garis pandang pengamat di Bumi. Pilihan A, B, dan C tidak didukung oleh teks.", "qtype": "inference"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('reading', 'Reading', 116, $${"id": "RD-27", "kind": "reading", "part": "Reading", "passageId": "RD-P3", "passageTitle": "The Hunt for Habitable Exoplanets", "passageText": "In 1992, astronomers confirmed the first planets ever found outside our solar system, and the floodgates opened. More than five thousand exoplanets have since been cataloged, and most were discovered by a single clever technique: the transit method. When a planet passes directly between its star and Earth, it blocks a tiny fraction of the star's light, causing a slight, periodic dimming. The Kepler space telescope, launched in 2009, stared at a single patch of sky for years, measuring these minute flickers, and in doing so revealed thousands of new worlds.\n\nFinding a planet is only the first step; the deeper question is whether any of them could support life. Astronomers focus on the habitable zone, sometimes called the Goldilocks zone, the range of distances from a star where temperatures might allow liquid water to exist on a planet's surface. Too close, and water boils away; too far, and it freezes solid. The exact boundaries depend on the type of star and the thickness of the planet's atmosphere, but this zone has become the primary hunting ground in the search for life.\n\nOne of the most promising hunting grounds is TRAPPIST-1, an ultracool dwarf star about 40 light-years from Earth. In 2017, astronomers announced that it hosts seven planets, each roughly the size of Earth, and three of them orbit within the star's habitable zone. The system is remarkably compact: all seven worlds circle their star at distances smaller than Mercury's orbit around the Sun, and they crowd so close together that from the surface of one, its neighbors would loom large in the sky.\n\nDetection, however, is not the same as habitability. A planet in the habitable zone might still be airless, or it might suffer sterilizing flares from an active star, or lack the magnetic field needed to protect an atmosphere. The James Webb Space Telescope can now probe the atmospheres of these distant worlds, and it may one day detect water vapor, methane, or oxygen, gases that, in combination, could be biosignatures of life. Until then, the habitable zone remains what it has always been: the best place to start looking.", "stem": "All of the following are mentioned in the passage as factors affecting a planet's habitability EXCEPT", "options": ["its distance from its star", "the number of moons orbiting it", "the composition of its atmosphere", "the activity level of its star"], "answer": 1, "explanation": "Jarak dari bintang disebut di paragraf 2, sedangkan komposisi atmosfer dan aktivitas bintang disebut di paragraf 4. Jumlah bulan yang mengorbit tidak pernah disebut dalam teks.", "qtype": "unstated detail"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('reading', 'Reading', 117, $${"id": "RD-28", "kind": "reading", "part": "Reading", "passageId": "RD-P3", "passageTitle": "The Hunt for Habitable Exoplanets", "passageText": "In 1992, astronomers confirmed the first planets ever found outside our solar system, and the floodgates opened. More than five thousand exoplanets have since been cataloged, and most were discovered by a single clever technique: the transit method. When a planet passes directly between its star and Earth, it blocks a tiny fraction of the star's light, causing a slight, periodic dimming. The Kepler space telescope, launched in 2009, stared at a single patch of sky for years, measuring these minute flickers, and in doing so revealed thousands of new worlds.\n\nFinding a planet is only the first step; the deeper question is whether any of them could support life. Astronomers focus on the habitable zone, sometimes called the Goldilocks zone, the range of distances from a star where temperatures might allow liquid water to exist on a planet's surface. Too close, and water boils away; too far, and it freezes solid. The exact boundaries depend on the type of star and the thickness of the planet's atmosphere, but this zone has become the primary hunting ground in the search for life.\n\nOne of the most promising hunting grounds is TRAPPIST-1, an ultracool dwarf star about 40 light-years from Earth. In 2017, astronomers announced that it hosts seven planets, each roughly the size of Earth, and three of them orbit within the star's habitable zone. The system is remarkably compact: all seven worlds circle their star at distances smaller than Mercury's orbit around the Sun, and they crowd so close together that from the surface of one, its neighbors would loom large in the sky.\n\nDetection, however, is not the same as habitability. A planet in the habitable zone might still be airless, or it might suffer sterilizing flares from an active star, or lack the magnetic field needed to protect an atmosphere. The James Webb Space Telescope can now probe the atmospheres of these distant worlds, and it may one day detect water vapor, methane, or oxygen, gases that, in combination, could be biosignatures of life. Until then, the habitable zone remains what it has always been: the best place to start looking.", "stem": "According to the passage, the Kepler space telescope", "options": ["was launched in 2017", "discovered the TRAPPIST-1 system", "revealed thousands of new worlds using the transit method", "studies only planets within our solar system"], "answer": 2, "explanation": "Paragraf 1 menyatakan Kepler diluncurkan pada 2009 dan mengungkap ribuan dunia baru. Pilihan A, B, dan D bertentangan dengan teks.", "qtype": "stated detail"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('reading', 'Reading', 118, $${"id": "RD-29", "kind": "reading", "part": "Reading", "passageId": "RD-P3", "passageTitle": "The Hunt for Habitable Exoplanets", "passageText": "In 1992, astronomers confirmed the first planets ever found outside our solar system, and the floodgates opened. More than five thousand exoplanets have since been cataloged, and most were discovered by a single clever technique: the transit method. When a planet passes directly between its star and Earth, it blocks a tiny fraction of the star's light, causing a slight, periodic dimming. The Kepler space telescope, launched in 2009, stared at a single patch of sky for years, measuring these minute flickers, and in doing so revealed thousands of new worlds.\n\nFinding a planet is only the first step; the deeper question is whether any of them could support life. Astronomers focus on the habitable zone, sometimes called the Goldilocks zone, the range of distances from a star where temperatures might allow liquid water to exist on a planet's surface. Too close, and water boils away; too far, and it freezes solid. The exact boundaries depend on the type of star and the thickness of the planet's atmosphere, but this zone has become the primary hunting ground in the search for life.\n\nOne of the most promising hunting grounds is TRAPPIST-1, an ultracool dwarf star about 40 light-years from Earth. In 2017, astronomers announced that it hosts seven planets, each roughly the size of Earth, and three of them orbit within the star's habitable zone. The system is remarkably compact: all seven worlds circle their star at distances smaller than Mercury's orbit around the Sun, and they crowd so close together that from the surface of one, its neighbors would loom large in the sky.\n\nDetection, however, is not the same as habitability. A planet in the habitable zone might still be airless, or it might suffer sterilizing flares from an active star, or lack the magnetic field needed to protect an atmosphere. The James Webb Space Telescope can now probe the atmospheres of these distant worlds, and it may one day detect water vapor, methane, or oxygen, gases that, in combination, could be biosignatures of life. Until then, the habitable zone remains what it has always been: the best place to start looking.", "stem": "The word 'probe' in paragraph 4 is closest in meaning to", "options": ["launch", "avoid", "ignore", "investigate"], "answer": 3, "explanation": "Frasa 'probe the atmospheres' berarti menyelidiki atau menganalisis atmosfer, jadi 'investigate'. Pilihan A, B, dan C tidak sesuai konteks.", "qtype": "vocabulary"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('reading', 'Reading', 119, $${"id": "RD-30", "kind": "reading", "part": "Reading", "passageId": "RD-P3", "passageTitle": "The Hunt for Habitable Exoplanets", "passageText": "In 1992, astronomers confirmed the first planets ever found outside our solar system, and the floodgates opened. More than five thousand exoplanets have since been cataloged, and most were discovered by a single clever technique: the transit method. When a planet passes directly between its star and Earth, it blocks a tiny fraction of the star's light, causing a slight, periodic dimming. The Kepler space telescope, launched in 2009, stared at a single patch of sky for years, measuring these minute flickers, and in doing so revealed thousands of new worlds.\n\nFinding a planet is only the first step; the deeper question is whether any of them could support life. Astronomers focus on the habitable zone, sometimes called the Goldilocks zone, the range of distances from a star where temperatures might allow liquid water to exist on a planet's surface. Too close, and water boils away; too far, and it freezes solid. The exact boundaries depend on the type of star and the thickness of the planet's atmosphere, but this zone has become the primary hunting ground in the search for life.\n\nOne of the most promising hunting grounds is TRAPPIST-1, an ultracool dwarf star about 40 light-years from Earth. In 2017, astronomers announced that it hosts seven planets, each roughly the size of Earth, and three of them orbit within the star's habitable zone. The system is remarkably compact: all seven worlds circle their star at distances smaller than Mercury's orbit around the Sun, and they crowd so close together that from the surface of one, its neighbors would loom large in the sky.\n\nDetection, however, is not the same as habitability. A planet in the habitable zone might still be airless, or it might suffer sterilizing flares from an active star, or lack the magnetic field needed to protect an atmosphere. The James Webb Space Telescope can now probe the atmospheres of these distant worlds, and it may one day detect water vapor, methane, or oxygen, gases that, in combination, could be biosignatures of life. Until then, the habitable zone remains what it has always been: the best place to start looking.", "stem": "Why does the author discuss TRAPPIST-1 in paragraph 3?", "options": ["To provide an example of a promising planetary system", "To prove that extraterrestrial life exists", "To criticize the Kepler mission", "To describe the star closest to Earth"], "answer": 0, "explanation": "TRAPPIST-1 disajikan sebagai 'one of the most promising hunting grounds', yaitu contoh sistem planet yang menjanjikan. Pilihan B terlalu jauh (teks tidak mengklaim bukti kehidupan), sedangkan C dan D tidak didukung teks.", "qtype": "purpose"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('reading', 'Reading', 120, $${"id": "RD-31", "kind": "reading", "part": "Reading", "passageId": "RD-P4", "passageTitle": "Saving da Vinci's 'The Last Supper'", "passageText": "Between 1495 and 1498, Leonardo da Vinci painted 'The Last Supper' on the wall of the dining hall, or refectory, of the monastery of Santa Maria delle Grazie in Milan. The work was commissioned by Ludovico Sforza, the Duke of Milan, who intended the monastery as a family mausoleum. He wanted a masterpiece worthy of his dynasty, and Leonardo, already famous as a painter and engineer, was the obvious choice.\n\nLeonardo, however, was never content with conventional methods. Instead of true fresco, in which pigment is applied to wet plaster so that the paint bonds with the wall as it dries, he painted in tempera and oils on dry plaster. The experimental technique gave him the luminous detail and the freedom to revise that he demanded, but it never bonded properly with the wall. The paint began to flake within his own lifetime. Later centuries added their own damage: dampness in the refectory, the building's use as a stable by occupying troops, and, in 1943, an Allied bomb that destroyed much of the monastery but miraculously spared the wall bearing the painting.\n\nBy the twentieth century, the masterpiece was a ghost of itself, buried under centuries of well-meaning but heavy-handed repainting. From 1978 to 1999, a team led by the restorer Pinin Brambilla Barcilon undertook a painstaking restoration, removing layer after layer of overpainting to recover what remained of Leonardo's original work. The project was controversial: some critics argued that so little of the artist's own hand survived that the restoration revealed more about modern conservation than about Leonardo. Modern climate-control systems were installed to stabilize the fragile wall.\n\nToday the painting survives, stabilized but still fragile. Visitors are admitted in small groups for only fifteen minutes, and tickets must be reserved far in advance. The restrictions frustrate some tourists, but they reflect a hard-won lesson: Leonardo's genius lay partly in his willingness to experiment, and 'The Last Supper' has been paying the price of that experiment for more than five hundred years.", "stem": "What is the main idea of the passage?", "options": ["Leonardo da Vinci was a better engineer than painter.", "Leonardo's experimental painting technique caused centuries of deterioration, making 'The Last Supper' a fragile masterpiece that requires constant protection.", "The 1978-1999 restoration completely destroyed the original painting.", "Napoleon's troops were the main cause of damage to 'The Last Supper.'"], "answer": 1, "explanation": "Gagasan utama merangkum teknik eksperimental yang menyebabkan kerusakan (paragraf 2), restorasi (paragraf 3), dan perlindungan ketat saat ini (paragraf 4). Pilihan A tidak dibahas. Pilihan C berlebihan karena teks hanya menyebut restorasi itu kontroversial, bukan menghancurkan. Pilihan D salah karena pasukan pendudukan hanya satu dari banyak faktor.", "qtype": "main idea"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('reading', 'Reading', 121, $${"id": "RD-32", "kind": "reading", "part": "Reading", "passageId": "RD-P4", "passageTitle": "Saving da Vinci's 'The Last Supper'", "passageText": "Between 1495 and 1498, Leonardo da Vinci painted 'The Last Supper' on the wall of the dining hall, or refectory, of the monastery of Santa Maria delle Grazie in Milan. The work was commissioned by Ludovico Sforza, the Duke of Milan, who intended the monastery as a family mausoleum. He wanted a masterpiece worthy of his dynasty, and Leonardo, already famous as a painter and engineer, was the obvious choice.\n\nLeonardo, however, was never content with conventional methods. Instead of true fresco, in which pigment is applied to wet plaster so that the paint bonds with the wall as it dries, he painted in tempera and oils on dry plaster. The experimental technique gave him the luminous detail and the freedom to revise that he demanded, but it never bonded properly with the wall. The paint began to flake within his own lifetime. Later centuries added their own damage: dampness in the refectory, the building's use as a stable by occupying troops, and, in 1943, an Allied bomb that destroyed much of the monastery but miraculously spared the wall bearing the painting.\n\nBy the twentieth century, the masterpiece was a ghost of itself, buried under centuries of well-meaning but heavy-handed repainting. From 1978 to 1999, a team led by the restorer Pinin Brambilla Barcilon undertook a painstaking restoration, removing layer after layer of overpainting to recover what remained of Leonardo's original work. The project was controversial: some critics argued that so little of the artist's own hand survived that the restoration revealed more about modern conservation than about Leonardo. Modern climate-control systems were installed to stabilize the fragile wall.\n\nToday the painting survives, stabilized but still fragile. Visitors are admitted in small groups for only fifteen minutes, and tickets must be reserved far in advance. The restrictions frustrate some tourists, but they reflect a hard-won lesson: Leonardo's genius lay partly in his willingness to experiment, and 'The Last Supper' has been paying the price of that experiment for more than five hundred years.", "stem": "The painting 'The Last Supper' is located in", "options": ["Florence", "Rome", "Milan", "Venice"], "answer": 2, "explanation": "Paragraf 1 menyatakan lukisan itu berada di biara Santa Maria delle Grazie di Milan. Pilihan A, B, dan D tidak disebut.", "qtype": "stated detail"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('reading', 'Reading', 122, $${"id": "RD-33", "kind": "reading", "part": "Reading", "passageId": "RD-P4", "passageTitle": "Saving da Vinci's 'The Last Supper'", "passageText": "Between 1495 and 1498, Leonardo da Vinci painted 'The Last Supper' on the wall of the dining hall, or refectory, of the monastery of Santa Maria delle Grazie in Milan. The work was commissioned by Ludovico Sforza, the Duke of Milan, who intended the monastery as a family mausoleum. He wanted a masterpiece worthy of his dynasty, and Leonardo, already famous as a painter and engineer, was the obvious choice.\n\nLeonardo, however, was never content with conventional methods. Instead of true fresco, in which pigment is applied to wet plaster so that the paint bonds with the wall as it dries, he painted in tempera and oils on dry plaster. The experimental technique gave him the luminous detail and the freedom to revise that he demanded, but it never bonded properly with the wall. The paint began to flake within his own lifetime. Later centuries added their own damage: dampness in the refectory, the building's use as a stable by occupying troops, and, in 1943, an Allied bomb that destroyed much of the monastery but miraculously spared the wall bearing the painting.\n\nBy the twentieth century, the masterpiece was a ghost of itself, buried under centuries of well-meaning but heavy-handed repainting. From 1978 to 1999, a team led by the restorer Pinin Brambilla Barcilon undertook a painstaking restoration, removing layer after layer of overpainting to recover what remained of Leonardo's original work. The project was controversial: some critics argued that so little of the artist's own hand survived that the restoration revealed more about modern conservation than about Leonardo. Modern climate-control systems were installed to stabilize the fragile wall.\n\nToday the painting survives, stabilized but still fragile. Visitors are admitted in small groups for only fifteen minutes, and tickets must be reserved far in advance. The restrictions frustrate some tourists, but they reflect a hard-won lesson: Leonardo's genius lay partly in his willingness to experiment, and 'The Last Supper' has been paying the price of that experiment for more than five hundred years.", "stem": "The word 'fragile' in paragraph 4 is closest in meaning to", "options": ["valuable", "famous", "ancient", "delicate"], "answer": 3, "explanation": "Konteksnya 'stabilized but still fragile' berarti lukisan masih rapuh dan mudah rusak, jadi 'delicate'. 'Valuable', 'famous', dan 'ancient' tidak menangkap makna kerapuhan.", "qtype": "vocabulary"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('reading', 'Reading', 123, $${"id": "RD-34", "kind": "reading", "part": "Reading", "passageId": "RD-P4", "passageTitle": "Saving da Vinci's 'The Last Supper'", "passageText": "Between 1495 and 1498, Leonardo da Vinci painted 'The Last Supper' on the wall of the dining hall, or refectory, of the monastery of Santa Maria delle Grazie in Milan. The work was commissioned by Ludovico Sforza, the Duke of Milan, who intended the monastery as a family mausoleum. He wanted a masterpiece worthy of his dynasty, and Leonardo, already famous as a painter and engineer, was the obvious choice.\n\nLeonardo, however, was never content with conventional methods. Instead of true fresco, in which pigment is applied to wet plaster so that the paint bonds with the wall as it dries, he painted in tempera and oils on dry plaster. The experimental technique gave him the luminous detail and the freedom to revise that he demanded, but it never bonded properly with the wall. The paint began to flake within his own lifetime. Later centuries added their own damage: dampness in the refectory, the building's use as a stable by occupying troops, and, in 1943, an Allied bomb that destroyed much of the monastery but miraculously spared the wall bearing the painting.\n\nBy the twentieth century, the masterpiece was a ghost of itself, buried under centuries of well-meaning but heavy-handed repainting. From 1978 to 1999, a team led by the restorer Pinin Brambilla Barcilon undertook a painstaking restoration, removing layer after layer of overpainting to recover what remained of Leonardo's original work. The project was controversial: some critics argued that so little of the artist's own hand survived that the restoration revealed more about modern conservation than about Leonardo. Modern climate-control systems were installed to stabilize the fragile wall.\n\nToday the painting survives, stabilized but still fragile. Visitors are admitted in small groups for only fifteen minutes, and tickets must be reserved far in advance. The restrictions frustrate some tourists, but they reflect a hard-won lesson: Leonardo's genius lay partly in his willingness to experiment, and 'The Last Supper' has been paying the price of that experiment for more than five hundred years.", "stem": "The word 'He' in paragraph 1 refers to", "options": ["Ludovico Sforza", "Leonardo da Vinci", "the head monk", "a modern restorer"], "answer": 0, "explanation": "Kata 'He' merujuk pada subjek kalimat sebelumnya, yaitu Ludovico Sforza, sang Adipati Milan yang memesan karya tersebut. Leonardo adalah pelukisnya, bukan pemesannya.", "qtype": "pronoun reference"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('reading', 'Reading', 124, $${"id": "RD-35", "kind": "reading", "part": "Reading", "passageId": "RD-P4", "passageTitle": "Saving da Vinci's 'The Last Supper'", "passageText": "Between 1495 and 1498, Leonardo da Vinci painted 'The Last Supper' on the wall of the dining hall, or refectory, of the monastery of Santa Maria delle Grazie in Milan. The work was commissioned by Ludovico Sforza, the Duke of Milan, who intended the monastery as a family mausoleum. He wanted a masterpiece worthy of his dynasty, and Leonardo, already famous as a painter and engineer, was the obvious choice.\n\nLeonardo, however, was never content with conventional methods. Instead of true fresco, in which pigment is applied to wet plaster so that the paint bonds with the wall as it dries, he painted in tempera and oils on dry plaster. The experimental technique gave him the luminous detail and the freedom to revise that he demanded, but it never bonded properly with the wall. The paint began to flake within his own lifetime. Later centuries added their own damage: dampness in the refectory, the building's use as a stable by occupying troops, and, in 1943, an Allied bomb that destroyed much of the monastery but miraculously spared the wall bearing the painting.\n\nBy the twentieth century, the masterpiece was a ghost of itself, buried under centuries of well-meaning but heavy-handed repainting. From 1978 to 1999, a team led by the restorer Pinin Brambilla Barcilon undertook a painstaking restoration, removing layer after layer of overpainting to recover what remained of Leonardo's original work. The project was controversial: some critics argued that so little of the artist's own hand survived that the restoration revealed more about modern conservation than about Leonardo. Modern climate-control systems were installed to stabilize the fragile wall.\n\nToday the painting survives, stabilized but still fragile. Visitors are admitted in small groups for only fifteen minutes, and tickets must be reserved far in advance. The restrictions frustrate some tourists, but they reflect a hard-won lesson: Leonardo's genius lay partly in his willingness to experiment, and 'The Last Supper' has been paying the price of that experiment for more than five hundred years.", "stem": "According to the passage, the paint began to deteriorate because Leonardo", "options": ["painted the work outdoors", "used colors that faded in sunlight", "applied paint to dry rather than wet plaster", "left the painting unfinished"], "answer": 2, "explanation": "Paragraf 2 menjelaskan Leonardo melukis dengan tempera dan minyak di atas plester kering, bukan fresco basah, sehingga cat tidak merekat dengan baik. Pilihan A, B, dan D tidak dinyatakan dalam teks.", "qtype": "stated detail"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('reading', 'Reading', 125, $${"id": "RD-36", "kind": "reading", "part": "Reading", "passageId": "RD-P4", "passageTitle": "Saving da Vinci's 'The Last Supper'", "passageText": "Between 1495 and 1498, Leonardo da Vinci painted 'The Last Supper' on the wall of the dining hall, or refectory, of the monastery of Santa Maria delle Grazie in Milan. The work was commissioned by Ludovico Sforza, the Duke of Milan, who intended the monastery as a family mausoleum. He wanted a masterpiece worthy of his dynasty, and Leonardo, already famous as a painter and engineer, was the obvious choice.\n\nLeonardo, however, was never content with conventional methods. Instead of true fresco, in which pigment is applied to wet plaster so that the paint bonds with the wall as it dries, he painted in tempera and oils on dry plaster. The experimental technique gave him the luminous detail and the freedom to revise that he demanded, but it never bonded properly with the wall. The paint began to flake within his own lifetime. Later centuries added their own damage: dampness in the refectory, the building's use as a stable by occupying troops, and, in 1943, an Allied bomb that destroyed much of the monastery but miraculously spared the wall bearing the painting.\n\nBy the twentieth century, the masterpiece was a ghost of itself, buried under centuries of well-meaning but heavy-handed repainting. From 1978 to 1999, a team led by the restorer Pinin Brambilla Barcilon undertook a painstaking restoration, removing layer after layer of overpainting to recover what remained of Leonardo's original work. The project was controversial: some critics argued that so little of the artist's own hand survived that the restoration revealed more about modern conservation than about Leonardo. Modern climate-control systems were installed to stabilize the fragile wall.\n\nToday the painting survives, stabilized but still fragile. Visitors are admitted in small groups for only fifteen minutes, and tickets must be reserved far in advance. The restrictions frustrate some tourists, but they reflect a hard-won lesson: Leonardo's genius lay partly in his willingness to experiment, and 'The Last Supper' has been paying the price of that experiment for more than five hundred years.", "stem": "It can be inferred from paragraph 2 that true fresco", "options": ["was invented by Leonardo da Vinci", "creates a durable bond between paint and wall", "cannot be used for large paintings", "always fades within a few decades"], "answer": 1, "explanation": "Teks menjelaskan pada fresco sejati pigmen diaplikasikan ke plester basah 'so that the paint bonds with the wall as it dries', yang menyiratkan ikatan yang awet. Leonardo justru menghindarinya demi detail dan kebebasan revisi. Pilihan A, C, dan D tidak didukung teks.", "qtype": "inference"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('reading', 'Reading', 126, $${"id": "RD-37", "kind": "reading", "part": "Reading", "passageId": "RD-P4", "passageTitle": "Saving da Vinci's 'The Last Supper'", "passageText": "Between 1495 and 1498, Leonardo da Vinci painted 'The Last Supper' on the wall of the dining hall, or refectory, of the monastery of Santa Maria delle Grazie in Milan. The work was commissioned by Ludovico Sforza, the Duke of Milan, who intended the monastery as a family mausoleum. He wanted a masterpiece worthy of his dynasty, and Leonardo, already famous as a painter and engineer, was the obvious choice.\n\nLeonardo, however, was never content with conventional methods. Instead of true fresco, in which pigment is applied to wet plaster so that the paint bonds with the wall as it dries, he painted in tempera and oils on dry plaster. The experimental technique gave him the luminous detail and the freedom to revise that he demanded, but it never bonded properly with the wall. The paint began to flake within his own lifetime. Later centuries added their own damage: dampness in the refectory, the building's use as a stable by occupying troops, and, in 1943, an Allied bomb that destroyed much of the monastery but miraculously spared the wall bearing the painting.\n\nBy the twentieth century, the masterpiece was a ghost of itself, buried under centuries of well-meaning but heavy-handed repainting. From 1978 to 1999, a team led by the restorer Pinin Brambilla Barcilon undertook a painstaking restoration, removing layer after layer of overpainting to recover what remained of Leonardo's original work. The project was controversial: some critics argued that so little of the artist's own hand survived that the restoration revealed more about modern conservation than about Leonardo. Modern climate-control systems were installed to stabilize the fragile wall.\n\nToday the painting survives, stabilized but still fragile. Visitors are admitted in small groups for only fifteen minutes, and tickets must be reserved far in advance. The restrictions frustrate some tourists, but they reflect a hard-won lesson: Leonardo's genius lay partly in his willingness to experiment, and 'The Last Supper' has been paying the price of that experiment for more than five hundred years.", "stem": "All of the following are mentioned as causes of damage to the painting EXCEPT", "options": ["dampness in the refectory", "Leonardo's experimental technique", "wartime bombing", "an earthquake in the nineteenth century"], "answer": 3, "explanation": "Kelembapan, teknik eksperimental, dan pengeboman masa perang semuanya disebut di paragraf 2 dan 3. Gempa bumi pada abad ke-19 tidak pernah disebut dalam teks.", "qtype": "unstated detail"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('reading', 'Reading', 127, $${"id": "RD-38", "kind": "reading", "part": "Reading", "passageId": "RD-P4", "passageTitle": "Saving da Vinci's 'The Last Supper'", "passageText": "Between 1495 and 1498, Leonardo da Vinci painted 'The Last Supper' on the wall of the dining hall, or refectory, of the monastery of Santa Maria delle Grazie in Milan. The work was commissioned by Ludovico Sforza, the Duke of Milan, who intended the monastery as a family mausoleum. He wanted a masterpiece worthy of his dynasty, and Leonardo, already famous as a painter and engineer, was the obvious choice.\n\nLeonardo, however, was never content with conventional methods. Instead of true fresco, in which pigment is applied to wet plaster so that the paint bonds with the wall as it dries, he painted in tempera and oils on dry plaster. The experimental technique gave him the luminous detail and the freedom to revise that he demanded, but it never bonded properly with the wall. The paint began to flake within his own lifetime. Later centuries added their own damage: dampness in the refectory, the building's use as a stable by occupying troops, and, in 1943, an Allied bomb that destroyed much of the monastery but miraculously spared the wall bearing the painting.\n\nBy the twentieth century, the masterpiece was a ghost of itself, buried under centuries of well-meaning but heavy-handed repainting. From 1978 to 1999, a team led by the restorer Pinin Brambilla Barcilon undertook a painstaking restoration, removing layer after layer of overpainting to recover what remained of Leonardo's original work. The project was controversial: some critics argued that so little of the artist's own hand survived that the restoration revealed more about modern conservation than about Leonardo. Modern climate-control systems were installed to stabilize the fragile wall.\n\nToday the painting survives, stabilized but still fragile. Visitors are admitted in small groups for only fifteen minutes, and tickets must be reserved far in advance. The restrictions frustrate some tourists, but they reflect a hard-won lesson: Leonardo's genius lay partly in his willingness to experiment, and 'The Last Supper' has been paying the price of that experiment for more than five hundred years.", "stem": "The word 'controversial' in paragraph 3 is closest in meaning to", "options": ["disputed", "expensive", "secret", "rapid"], "answer": 0, "explanation": "Konteksnya: para kritikus memperdebatkan apakah yang tersisa masih karya tangan Leonardo, jadi 'controversial' berarti diperdebatkan atau 'disputed'. Pilihan B, C, dan D tidak sesuai konteks.", "qtype": "vocabulary"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('reading', 'Reading', 128, $${"id": "RD-39", "kind": "reading", "part": "Reading", "passageId": "RD-P4", "passageTitle": "Saving da Vinci's 'The Last Supper'", "passageText": "Between 1495 and 1498, Leonardo da Vinci painted 'The Last Supper' on the wall of the dining hall, or refectory, of the monastery of Santa Maria delle Grazie in Milan. The work was commissioned by Ludovico Sforza, the Duke of Milan, who intended the monastery as a family mausoleum. He wanted a masterpiece worthy of his dynasty, and Leonardo, already famous as a painter and engineer, was the obvious choice.\n\nLeonardo, however, was never content with conventional methods. Instead of true fresco, in which pigment is applied to wet plaster so that the paint bonds with the wall as it dries, he painted in tempera and oils on dry plaster. The experimental technique gave him the luminous detail and the freedom to revise that he demanded, but it never bonded properly with the wall. The paint began to flake within his own lifetime. Later centuries added their own damage: dampness in the refectory, the building's use as a stable by occupying troops, and, in 1943, an Allied bomb that destroyed much of the monastery but miraculously spared the wall bearing the painting.\n\nBy the twentieth century, the masterpiece was a ghost of itself, buried under centuries of well-meaning but heavy-handed repainting. From 1978 to 1999, a team led by the restorer Pinin Brambilla Barcilon undertook a painstaking restoration, removing layer after layer of overpainting to recover what remained of Leonardo's original work. The project was controversial: some critics argued that so little of the artist's own hand survived that the restoration revealed more about modern conservation than about Leonardo. Modern climate-control systems were installed to stabilize the fragile wall.\n\nToday the painting survives, stabilized but still fragile. Visitors are admitted in small groups for only fifteen minutes, and tickets must be reserved far in advance. The restrictions frustrate some tourists, but they reflect a hard-won lesson: Leonardo's genius lay partly in his willingness to experiment, and 'The Last Supper' has been paying the price of that experiment for more than five hundred years.", "stem": "According to the passage, the 1978-1999 restoration", "options": ["moved the painting to a museum", "was completed in a single year", "removed later layers of overpainting to recover Leonardo's original work", "repainted the missing sections entirely from imagination"], "answer": 2, "explanation": "Paragraf 3 menyatakan tim restorasi menghilangkan lapisan demi lapisan cat tambahan untuk memulihkan karya asli Leonardo. Pilihan A, B, dan D bertentangan dengan teks.", "qtype": "stated detail"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('reading', 'Reading', 129, $${"id": "RD-40", "kind": "reading", "part": "Reading", "passageId": "RD-P4", "passageTitle": "Saving da Vinci's 'The Last Supper'", "passageText": "Between 1495 and 1498, Leonardo da Vinci painted 'The Last Supper' on the wall of the dining hall, or refectory, of the monastery of Santa Maria delle Grazie in Milan. The work was commissioned by Ludovico Sforza, the Duke of Milan, who intended the monastery as a family mausoleum. He wanted a masterpiece worthy of his dynasty, and Leonardo, already famous as a painter and engineer, was the obvious choice.\n\nLeonardo, however, was never content with conventional methods. Instead of true fresco, in which pigment is applied to wet plaster so that the paint bonds with the wall as it dries, he painted in tempera and oils on dry plaster. The experimental technique gave him the luminous detail and the freedom to revise that he demanded, but it never bonded properly with the wall. The paint began to flake within his own lifetime. Later centuries added their own damage: dampness in the refectory, the building's use as a stable by occupying troops, and, in 1943, an Allied bomb that destroyed much of the monastery but miraculously spared the wall bearing the painting.\n\nBy the twentieth century, the masterpiece was a ghost of itself, buried under centuries of well-meaning but heavy-handed repainting. From 1978 to 1999, a team led by the restorer Pinin Brambilla Barcilon undertook a painstaking restoration, removing layer after layer of overpainting to recover what remained of Leonardo's original work. The project was controversial: some critics argued that so little of the artist's own hand survived that the restoration revealed more about modern conservation than about Leonardo. Modern climate-control systems were installed to stabilize the fragile wall.\n\nToday the painting survives, stabilized but still fragile. Visitors are admitted in small groups for only fifteen minutes, and tickets must be reserved far in advance. The restrictions frustrate some tourists, but they reflect a hard-won lesson: Leonardo's genius lay partly in his willingness to experiment, and 'The Last Supper' has been paying the price of that experiment for more than five hundred years.", "stem": "What does the passage suggest about visiting 'The Last Supper' today?", "options": ["Visitors may stay as long as they wish", "Access is strictly limited to protect the fragile work", "The painting has been moved to a new building", "Photography is encouraged to aid restoration"], "answer": 1, "explanation": "Paragraf 4 menyebut pengunjung hanya diizinkan dalam kelompok kecil selama lima belas menit dengan reservasi jauh hari, yang menunjukkan pembatasan ketat demi perlindungan. Pilihan A, C, dan D tidak didukung teks.", "qtype": "inference"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('reading', 'Reading', 130, $${"id": "RD-41", "kind": "reading", "part": "Reading", "passageId": "RD-P5", "passageTitle": "Sleep and the Consolidation of Memory", "passageText": "Sleep was once regarded as a passive state, a mere switching-off of the brain. Modern research has overturned that view entirely. The sleeping brain is intensely active, cycling through distinct stages roughly every ninety minutes. The two broad categories are REM sleep, named for the rapid eye movements beneath closed lids and associated with vivid dreaming, and non-REM sleep, which includes the deep, slow-wave sleep that dominates the first half of the night.\n\nOne of the most important jobs performed during sleep is the consolidation of memory. The hippocampus, a small structure deep in the brain, acts as a temporary storehouse for the day's experiences. It holds them briefly during the night, while deep slow-wave sleep replays and files them away in the cortex for long-term storage. The evidence is striking: in study after study, subjects deprived of sleep perform markedly worse on tests of recall than those allowed a full night's rest.\n\nREM sleep appears to handle a different assignment. It plays a key role in procedural memory, the kind involved in learning skills such as playing a musical instrument, and in processing emotional experiences. Researchers suspect that the bizarre narratives of dreams may be the brain's way of defusing the emotional charge of difficult memories, filing them away in a less distressing form.\n\nThe practical message is clear, and it runs counter to student folklore. Cramming through the night before an examination is counterproductive: the exhausted brain cannot consolidate what it has just studied. Even a short nap of twenty to ninety minutes has been shown to aid memory, and chronic sleep disruption, as in disorders such as sleep apnea, is linked to lasting memory problems. Good sleep hygiene, regular hours, a dark room, and reasonable limits on late-night screen time, may be the most underrated study aid of all.", "stem": "What is the main idea of the passage?", "options": ["Sleep is an active brain state that consolidates memories, so sacrificing sleep for extra study is counterproductive.", "Dreams have no function whatsoever.", "Sleep apnea is the most common sleep disorder in the world.", "The hippocampus stops working during sleep."], "answer": 0, "explanation": "Gagasan utama merangkum peran aktif tidur dalam konsolidasi memori (paragraf 1-3) dan pesan praktisnya (paragraf 4). Pilihan B berlawanan dengan paragraf 3. Pilihan C tidak dinyatakan ('most common' tidak disebut). Pilihan D salah karena hipokampus justru aktif saat tidur.", "qtype": "main idea"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('reading', 'Reading', 131, $${"id": "RD-42", "kind": "reading", "part": "Reading", "passageId": "RD-P5", "passageTitle": "Sleep and the Consolidation of Memory", "passageText": "Sleep was once regarded as a passive state, a mere switching-off of the brain. Modern research has overturned that view entirely. The sleeping brain is intensely active, cycling through distinct stages roughly every ninety minutes. The two broad categories are REM sleep, named for the rapid eye movements beneath closed lids and associated with vivid dreaming, and non-REM sleep, which includes the deep, slow-wave sleep that dominates the first half of the night.\n\nOne of the most important jobs performed during sleep is the consolidation of memory. The hippocampus, a small structure deep in the brain, acts as a temporary storehouse for the day's experiences. It holds them briefly during the night, while deep slow-wave sleep replays and files them away in the cortex for long-term storage. The evidence is striking: in study after study, subjects deprived of sleep perform markedly worse on tests of recall than those allowed a full night's rest.\n\nREM sleep appears to handle a different assignment. It plays a key role in procedural memory, the kind involved in learning skills such as playing a musical instrument, and in processing emotional experiences. Researchers suspect that the bizarre narratives of dreams may be the brain's way of defusing the emotional charge of difficult memories, filing them away in a less distressing form.\n\nThe practical message is clear, and it runs counter to student folklore. Cramming through the night before an examination is counterproductive: the exhausted brain cannot consolidate what it has just studied. Even a short nap of twenty to ninety minutes has been shown to aid memory, and chronic sleep disruption, as in disorders such as sleep apnea, is linked to lasting memory problems. Good sleep hygiene, regular hours, a dark room, and reasonable limits on late-night screen time, may be the most underrated study aid of all.", "stem": "According to paragraph 2, during deep slow-wave sleep", "options": ["the brain becomes completely inactive", "the most vivid dreams occur", "the body experiences total muscle paralysis", "memories are transferred from the hippocampus to the cortex"], "answer": 3, "explanation": "Paragraf 2 menyatakan memori diputar ulang dan 'files them away in the cortex for long-term storage'. Pilihan A berlawanan dengan teks, sedangkan B dan C adalah ciri tidur REM, bukan tidur gelombang lambat.", "qtype": "stated detail"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('reading', 'Reading', 132, $${"id": "RD-43", "kind": "reading", "part": "Reading", "passageId": "RD-P5", "passageTitle": "Sleep and the Consolidation of Memory", "passageText": "Sleep was once regarded as a passive state, a mere switching-off of the brain. Modern research has overturned that view entirely. The sleeping brain is intensely active, cycling through distinct stages roughly every ninety minutes. The two broad categories are REM sleep, named for the rapid eye movements beneath closed lids and associated with vivid dreaming, and non-REM sleep, which includes the deep, slow-wave sleep that dominates the first half of the night.\n\nOne of the most important jobs performed during sleep is the consolidation of memory. The hippocampus, a small structure deep in the brain, acts as a temporary storehouse for the day's experiences. It holds them briefly during the night, while deep slow-wave sleep replays and files them away in the cortex for long-term storage. The evidence is striking: in study after study, subjects deprived of sleep perform markedly worse on tests of recall than those allowed a full night's rest.\n\nREM sleep appears to handle a different assignment. It plays a key role in procedural memory, the kind involved in learning skills such as playing a musical instrument, and in processing emotional experiences. Researchers suspect that the bizarre narratives of dreams may be the brain's way of defusing the emotional charge of difficult memories, filing them away in a less distressing form.\n\nThe practical message is clear, and it runs counter to student folklore. Cramming through the night before an examination is counterproductive: the exhausted brain cannot consolidate what it has just studied. Even a short nap of twenty to ninety minutes has been shown to aid memory, and chronic sleep disruption, as in disorders such as sleep apnea, is linked to lasting memory problems. Good sleep hygiene, regular hours, a dark room, and reasonable limits on late-night screen time, may be the most underrated study aid of all.", "stem": "The word 'counterproductive' in paragraph 4 is closest in meaning to", "options": ["exhausting", "self-defeating", "uncommon", "forbidden"], "answer": 1, "explanation": "Konteksnya: begadang sebelum ujian 'counterproductive' karena justru menggagalkan tujuan belajar, jadi 'self-defeating' (merugikan diri sendiri). 'Exhausting' hanya menangkap sebagian makna, sedangkan 'uncommon' dan 'forbidden' tidak tepat.", "qtype": "vocabulary"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('reading', 'Reading', 133, $${"id": "RD-44", "kind": "reading", "part": "Reading", "passageId": "RD-P5", "passageTitle": "Sleep and the Consolidation of Memory", "passageText": "Sleep was once regarded as a passive state, a mere switching-off of the brain. Modern research has overturned that view entirely. The sleeping brain is intensely active, cycling through distinct stages roughly every ninety minutes. The two broad categories are REM sleep, named for the rapid eye movements beneath closed lids and associated with vivid dreaming, and non-REM sleep, which includes the deep, slow-wave sleep that dominates the first half of the night.\n\nOne of the most important jobs performed during sleep is the consolidation of memory. The hippocampus, a small structure deep in the brain, acts as a temporary storehouse for the day's experiences. It holds them briefly during the night, while deep slow-wave sleep replays and files them away in the cortex for long-term storage. The evidence is striking: in study after study, subjects deprived of sleep perform markedly worse on tests of recall than those allowed a full night's rest.\n\nREM sleep appears to handle a different assignment. It plays a key role in procedural memory, the kind involved in learning skills such as playing a musical instrument, and in processing emotional experiences. Researchers suspect that the bizarre narratives of dreams may be the brain's way of defusing the emotional charge of difficult memories, filing them away in a less distressing form.\n\nThe practical message is clear, and it runs counter to student folklore. Cramming through the night before an examination is counterproductive: the exhausted brain cannot consolidate what it has just studied. Even a short nap of twenty to ninety minutes has been shown to aid memory, and chronic sleep disruption, as in disorders such as sleep apnea, is linked to lasting memory problems. Good sleep hygiene, regular hours, a dark room, and reasonable limits on late-night screen time, may be the most underrated study aid of all.", "stem": "The word 'It' in paragraph 2 refers to", "options": ["the cortex", "the dream", "the hippocampus", "the night"], "answer": 2, "explanation": "Kata 'It' merujuk pada subjek kalimat sebelumnya, yaitu 'The hippocampus'. Pilihan A adalah tujuan penyimpanan, bukan acuannya.", "qtype": "pronoun reference"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('reading', 'Reading', 134, $${"id": "RD-45", "kind": "reading", "part": "Reading", "passageId": "RD-P5", "passageTitle": "Sleep and the Consolidation of Memory", "passageText": "Sleep was once regarded as a passive state, a mere switching-off of the brain. Modern research has overturned that view entirely. The sleeping brain is intensely active, cycling through distinct stages roughly every ninety minutes. The two broad categories are REM sleep, named for the rapid eye movements beneath closed lids and associated with vivid dreaming, and non-REM sleep, which includes the deep, slow-wave sleep that dominates the first half of the night.\n\nOne of the most important jobs performed during sleep is the consolidation of memory. The hippocampus, a small structure deep in the brain, acts as a temporary storehouse for the day's experiences. It holds them briefly during the night, while deep slow-wave sleep replays and files them away in the cortex for long-term storage. The evidence is striking: in study after study, subjects deprived of sleep perform markedly worse on tests of recall than those allowed a full night's rest.\n\nREM sleep appears to handle a different assignment. It plays a key role in procedural memory, the kind involved in learning skills such as playing a musical instrument, and in processing emotional experiences. Researchers suspect that the bizarre narratives of dreams may be the brain's way of defusing the emotional charge of difficult memories, filing them away in a less distressing form.\n\nThe practical message is clear, and it runs counter to student folklore. Cramming through the night before an examination is counterproductive: the exhausted brain cannot consolidate what it has just studied. Even a short nap of twenty to ninety minutes has been shown to aid memory, and chronic sleep disruption, as in disorders such as sleep apnea, is linked to lasting memory problems. Good sleep hygiene, regular hours, a dark room, and reasonable limits on late-night screen time, may be the most underrated study aid of all.", "stem": "All of the following are associated with REM sleep in the passage EXCEPT", "options": ["vivid dreaming", "rapid eye movements", "processing emotional experiences", "transferring facts to the cortex for long-term storage"], "answer": 3, "explanation": "Mimpi yang jelas, gerakan mata cepat, dan pemrosesan emosi adalah ciri REM (paragraf 1 dan 3). Pemindahan fakta ke korteks terjadi selama tidur gelombang lambat (paragraf 2), bukan REM.", "qtype": "unstated detail"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('reading', 'Reading', 135, $${"id": "RD-46", "kind": "reading", "part": "Reading", "passageId": "RD-P5", "passageTitle": "Sleep and the Consolidation of Memory", "passageText": "Sleep was once regarded as a passive state, a mere switching-off of the brain. Modern research has overturned that view entirely. The sleeping brain is intensely active, cycling through distinct stages roughly every ninety minutes. The two broad categories are REM sleep, named for the rapid eye movements beneath closed lids and associated with vivid dreaming, and non-REM sleep, which includes the deep, slow-wave sleep that dominates the first half of the night.\n\nOne of the most important jobs performed during sleep is the consolidation of memory. The hippocampus, a small structure deep in the brain, acts as a temporary storehouse for the day's experiences. It holds them briefly during the night, while deep slow-wave sleep replays and files them away in the cortex for long-term storage. The evidence is striking: in study after study, subjects deprived of sleep perform markedly worse on tests of recall than those allowed a full night's rest.\n\nREM sleep appears to handle a different assignment. It plays a key role in procedural memory, the kind involved in learning skills such as playing a musical instrument, and in processing emotional experiences. Researchers suspect that the bizarre narratives of dreams may be the brain's way of defusing the emotional charge of difficult memories, filing them away in a less distressing form.\n\nThe practical message is clear, and it runs counter to student folklore. Cramming through the night before an examination is counterproductive: the exhausted brain cannot consolidate what it has just studied. Even a short nap of twenty to ninety minutes has been shown to aid memory, and chronic sleep disruption, as in disorders such as sleep apnea, is linked to lasting memory problems. Good sleep hygiene, regular hours, a dark room, and reasonable limits on late-night screen time, may be the most underrated study aid of all.", "stem": "It can be inferred from the passage that studying all night before an exam", "options": ["is less effective than studying earlier and then sleeping", "has no effect on memory at all", "only harms physical health, not memory", "is recommended for procedural skills"], "answer": 0, "explanation": "Paragraf 4 menyatakan begadang itu counterproductive karena otak yang kelelahan tidak dapat mengonsolidasi materi, sedangkan tidur justru membantu memori. Pilihan B, C, dan D tidak didukung teks.", "qtype": "inference"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('reading', 'Reading', 136, $${"id": "RD-47", "kind": "reading", "part": "Reading", "passageId": "RD-P5", "passageTitle": "Sleep and the Consolidation of Memory", "passageText": "Sleep was once regarded as a passive state, a mere switching-off of the brain. Modern research has overturned that view entirely. The sleeping brain is intensely active, cycling through distinct stages roughly every ninety minutes. The two broad categories are REM sleep, named for the rapid eye movements beneath closed lids and associated with vivid dreaming, and non-REM sleep, which includes the deep, slow-wave sleep that dominates the first half of the night.\n\nOne of the most important jobs performed during sleep is the consolidation of memory. The hippocampus, a small structure deep in the brain, acts as a temporary storehouse for the day's experiences. It holds them briefly during the night, while deep slow-wave sleep replays and files them away in the cortex for long-term storage. The evidence is striking: in study after study, subjects deprived of sleep perform markedly worse on tests of recall than those allowed a full night's rest.\n\nREM sleep appears to handle a different assignment. It plays a key role in procedural memory, the kind involved in learning skills such as playing a musical instrument, and in processing emotional experiences. Researchers suspect that the bizarre narratives of dreams may be the brain's way of defusing the emotional charge of difficult memories, filing them away in a less distressing form.\n\nThe practical message is clear, and it runs counter to student folklore. Cramming through the night before an examination is counterproductive: the exhausted brain cannot consolidate what it has just studied. Even a short nap of twenty to ninety minutes has been shown to aid memory, and chronic sleep disruption, as in disorders such as sleep apnea, is linked to lasting memory problems. Good sleep hygiene, regular hours, a dark room, and reasonable limits on late-night screen time, may be the most underrated study aid of all.", "stem": "According to studies mentioned in the passage, people deprived of sleep", "options": ["dream more vividly than others", "develop larger hippocampi", "perform worse on tests of recall", "consolidate memories more quickly"], "answer": 2, "explanation": "Paragraf 2 menyatakan subjek yang kurang tidur 'perform markedly worse on tests of recall'. Pilihan A, B, dan D tidak disebut atau bertentangan dengan teks.", "qtype": "stated detail"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('reading', 'Reading', 137, $${"id": "RD-48", "kind": "reading", "part": "Reading", "passageId": "RD-P5", "passageTitle": "Sleep and the Consolidation of Memory", "passageText": "Sleep was once regarded as a passive state, a mere switching-off of the brain. Modern research has overturned that view entirely. The sleeping brain is intensely active, cycling through distinct stages roughly every ninety minutes. The two broad categories are REM sleep, named for the rapid eye movements beneath closed lids and associated with vivid dreaming, and non-REM sleep, which includes the deep, slow-wave sleep that dominates the first half of the night.\n\nOne of the most important jobs performed during sleep is the consolidation of memory. The hippocampus, a small structure deep in the brain, acts as a temporary storehouse for the day's experiences. It holds them briefly during the night, while deep slow-wave sleep replays and files them away in the cortex for long-term storage. The evidence is striking: in study after study, subjects deprived of sleep perform markedly worse on tests of recall than those allowed a full night's rest.\n\nREM sleep appears to handle a different assignment. It plays a key role in procedural memory, the kind involved in learning skills such as playing a musical instrument, and in processing emotional experiences. Researchers suspect that the bizarre narratives of dreams may be the brain's way of defusing the emotional charge of difficult memories, filing them away in a less distressing form.\n\nThe practical message is clear, and it runs counter to student folklore. Cramming through the night before an examination is counterproductive: the exhausted brain cannot consolidate what it has just studied. Even a short nap of twenty to ninety minutes has been shown to aid memory, and chronic sleep disruption, as in disorders such as sleep apnea, is linked to lasting memory problems. Good sleep hygiene, regular hours, a dark room, and reasonable limits on late-night screen time, may be the most underrated study aid of all.", "stem": "The phrase 'sleep hygiene' in paragraph 4 is closest in meaning to", "options": ["medical treatment for insomnia", "healthy sleep habits and practices", "cleanliness of bed sheets", "surgery to improve breathing"], "answer": 1, "explanation": "Konteksnya, 'regular hours, a dark room, and reasonable limits on late-night screen time', merujuk pada kebiasaan dan praktik tidur yang sehat. Pilihan A dan D terlalu medis, sedangkan C menafsirkan 'hygiene' secara terlalu harfiah.", "qtype": "vocabulary"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('reading', 'Reading', 138, $${"id": "RD-49", "kind": "reading", "part": "Reading", "passageId": "RD-P5", "passageTitle": "Sleep and the Consolidation of Memory", "passageText": "Sleep was once regarded as a passive state, a mere switching-off of the brain. Modern research has overturned that view entirely. The sleeping brain is intensely active, cycling through distinct stages roughly every ninety minutes. The two broad categories are REM sleep, named for the rapid eye movements beneath closed lids and associated with vivid dreaming, and non-REM sleep, which includes the deep, slow-wave sleep that dominates the first half of the night.\n\nOne of the most important jobs performed during sleep is the consolidation of memory. The hippocampus, a small structure deep in the brain, acts as a temporary storehouse for the day's experiences. It holds them briefly during the night, while deep slow-wave sleep replays and files them away in the cortex for long-term storage. The evidence is striking: in study after study, subjects deprived of sleep perform markedly worse on tests of recall than those allowed a full night's rest.\n\nREM sleep appears to handle a different assignment. It plays a key role in procedural memory, the kind involved in learning skills such as playing a musical instrument, and in processing emotional experiences. Researchers suspect that the bizarre narratives of dreams may be the brain's way of defusing the emotional charge of difficult memories, filing them away in a less distressing form.\n\nThe practical message is clear, and it runs counter to student folklore. Cramming through the night before an examination is counterproductive: the exhausted brain cannot consolidate what it has just studied. Even a short nap of twenty to ninety minutes has been shown to aid memory, and chronic sleep disruption, as in disorders such as sleep apnea, is linked to lasting memory problems. Good sleep hygiene, regular hours, a dark room, and reasonable limits on late-night screen time, may be the most underrated study aid of all.", "stem": "The author would most likely agree that", "options": ["dreams are meaningless random images", "students should never take naps", "memory works best without any sleep", "a short nap can be more helpful than additional hours of tired studying"], "answer": 3, "explanation": "Paragraf 4 menyatakan tidur siang singkat terbukti membantu memori dan begadang itu counterproductive. Pilihan A berlawanan dengan paragraf 3, sedangkan B dan C bertentangan dengan keseluruhan teks.", "qtype": "inference"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('reading', 'Reading', 139, $${"id": "RD-50", "kind": "reading", "part": "Reading", "passageId": "RD-P5", "passageTitle": "Sleep and the Consolidation of Memory", "passageText": "Sleep was once regarded as a passive state, a mere switching-off of the brain. Modern research has overturned that view entirely. The sleeping brain is intensely active, cycling through distinct stages roughly every ninety minutes. The two broad categories are REM sleep, named for the rapid eye movements beneath closed lids and associated with vivid dreaming, and non-REM sleep, which includes the deep, slow-wave sleep that dominates the first half of the night.\n\nOne of the most important jobs performed during sleep is the consolidation of memory. The hippocampus, a small structure deep in the brain, acts as a temporary storehouse for the day's experiences. It holds them briefly during the night, while deep slow-wave sleep replays and files them away in the cortex for long-term storage. The evidence is striking: in study after study, subjects deprived of sleep perform markedly worse on tests of recall than those allowed a full night's rest.\n\nREM sleep appears to handle a different assignment. It plays a key role in procedural memory, the kind involved in learning skills such as playing a musical instrument, and in processing emotional experiences. Researchers suspect that the bizarre narratives of dreams may be the brain's way of defusing the emotional charge of difficult memories, filing them away in a less distressing form.\n\nThe practical message is clear, and it runs counter to student folklore. Cramming through the night before an examination is counterproductive: the exhausted brain cannot consolidate what it has just studied. Even a short nap of twenty to ninety minutes has been shown to aid memory, and chronic sleep disruption, as in disorders such as sleep apnea, is linked to lasting memory problems. Good sleep hygiene, regular hours, a dark room, and reasonable limits on late-night screen time, may be the most underrated study aid of all.", "stem": "The primary purpose of the passage is to", "options": ["describe treatments for sleep apnea", "compare the brains of humans and animals", "explain how sleep contributes to memory", "warn readers against dreaming"], "answer": 2, "explanation": "Keseluruhan teks menjelaskan peran tidur dalam konsolidasi memori. Pilihan A hanya disinggung sekilas, sedangkan B dan D tidak dibahas sama sekali.", "qtype": "purpose"}$$::jsonb);
